154			requests:     make(map[string]*Request),
155			commitments:  make(map[string]*Commitment),
156			usages:       make(map[string]*Usage),
157			firstResults: make(map[string]Commitment),
158			history:      make(map[string][]HistoryRecord),
159		}
160	}
161	
162	// RegisterProduct 登记产品：购买时刻、保修天数和除外故障代码。
163	// 编号重复时返回 ErrDuplicateID 且保留原记录。
164	func (s *Store) RegisterProduct(id string, purchaseTime time.Time, warrantyDays int, excludedCodes []string) error {
165		if id == "" {
166			return fmt.Errorf("%w: product id must not be empty", ErrInvalidParam)
167		}
168		if warrantyDays <= 0 {
169			return fmt.Errorf("%w: warranty days must be a positive integer", ErrInvalidParam)
170		}
171		s.mu.Lock()
172		defer s.mu.Unlock()
173		if _, ok := s.products[id]; ok {
174			return fmt.Errorf("%w: product %q", ErrDuplicateID, id)
175		}
176		codes := make(map[string]struct{}, len(excludedCodes))
177		for _, c := range excludedCodes {
178			if c == "" {
179				return fmt.Errorf("%w: excluded fault code must not be empty", ErrInvalidParam)
180			}
181			codes[c] = struct{}{}
182		}
183		s.products[id] = &Product{
184			ID:            id,
185			PurchaseTime:  purchaseTime,
186			WarrantyDays:  warrantyDays,
187			ExcludedCodes: codes,
188		}
189		return nil
190	}
