345			t.Fatalf("idempotent use: %v", err)
346		}
347		if u2.ID != u1.ID || u2.Quantity != 2 {
348			t.Fatalf("retry returned different usage: %+v vs %+v", u2, u1)
349		}
350		c, _ := s.Commitment("c1")
351		if c.Used != 2 {
352			t.Fatalf("idempotent use double-deducted: used=%d", c.Used)
353		}
354		// 改数量 / 改承诺 → 冲突。
355		if _, err := s.Use("u1", "c1", 3, nowOK); !errors.Is(err, ErrConflict) {
356			t.Fatalf("conflict on quantity: got %v", err)
357		}
358		if _, err := s.Use("u1", "c2", 2, nowOK); !errors.Is(err, ErrConflict) {
359			t.Fatalf("conflict on commitment: got %v", err)
360		}
361		// 冲突不改变记录。
362		c2, _ := s.Commitment("c1")
363		if c2.Used != 2 {
364			t.Fatalf("conflict changed usage: used=%d", c2.Used)
365		}
366	}
