// TestExclusionMatchingRemainsExactAndCaseSensitive 沿用故障代码现有的精确
// 匹配方式：不做大小写转换或代码修剪，大小写或首尾空白不同的代码是另一
// 个代码，仍应合格。
func TestExclusionMatchingRemainsExactAndCaseSensitive(t *testing.T) {
